fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    // Create a new vector with the same length, mapping each char
    // If it's an ASCII lowercase letter ('a' to 'z'), convert to uppercase
    // Otherwise, preserve as is.
    str1.iter()
        .map(|&c| {
            if ('a'..='z').contains(&c) {
                // Convert lowercase ASCII to uppercase by subtracting difference
                ((c as u8) - b'a' + b'A') as char
            } else {
                c
            }
        })
        .collect()
}